/* Skin "kodama-grove" (Kodama Grove): the tweakcn preset "kodama-grove" (Apache-2.0, see NOTICE.md), written by packages/skins/tools/tweakcn-skins.ts.
   On when data-skin="kodama-grove" is on <html> (the page) or on any element (a tile of /skins/). Values as tweakcn exports them;
   the spacing scale stays the kit's 0.25rem. Fonts: Merriweather (Google Fonts, loaded when the skin is on). */
[data-skin="kodama-grove"] {
  --background: hsl(45 49% 79%);
  --foreground: hsl(26 19% 30%);
  --card: hsl(42 45% 83%);
  --card-foreground: hsl(26 19% 30%);
  --popover: hsl(44 58% 89%);
  --popover-foreground: hsl(26 19% 30%);
  --primary: hsl(70.6 48.5% 32%);
  --primary-foreground: hsl(43 64% 98%);
  --secondary: hsl(45 48% 75%);
  --secondary-foreground: hsl(26 19% 30%);
  --muted: hsl(45 48% 75%);
  --muted-foreground: hsl(26.4 14.6% 33.5%);
  --accent: hsl(44 50% 72%);
  --accent-foreground: hsl(26 19% 30%);
  --destructive: hsl(8.5 34.7% 48%);
  --destructive-foreground: hsl(45 44.4% 96.5%);
  --border: hsl(26 24% 60%);
  --input: hsl(44 50% 72%);
  --ring: hsl(92 19% 62%);
  --chart-1: hsl(92 19% 62%);
  --chart-2: hsl(95 16% 55%);
  --chart-3: hsl(103 16% 75%);
  --chart-4: hsl(104 11% 47%);
  --chart-5: hsl(104 11% 39%);
  --sidebar: hsl(44 52% 76%);
  --sidebar-foreground: hsl(26 19% 30%);
  --sidebar-primary: hsl(92 19% 62%);
  --sidebar-primary-foreground: hsl(43 64% 98%);
  --sidebar-accent: hsl(42 29% 88%);
  --sidebar-accent-foreground: hsl(26 19% 30%);
  --sidebar-border: hsl(42 25% 86%);
  --sidebar-ring: hsl(92 19% 62%);
  --font-sans: Merriweather, serif;
  --font-serif: Source Serif 4, serif;
  --font-mono: JetBrains Mono, monospace;
  --radius: 0.425rem;
  --shadow-2xs: 3px 3px 2px 0px hsl(88 22% 35% / 0.07);
  --shadow-xs: 3px 3px 2px 0px hsl(88 22% 35% / 0.07);
  --shadow-sm: 3px 3px 2px 0px hsl(88 22% 35% / 0.15), 3px 1px 2px -1px hsl(88 22% 35% / 0.15);
  --shadow: 3px 3px 2px 0px hsl(88 22% 35% / 0.15), 3px 1px 2px -1px hsl(88 22% 35% / 0.15);
  --shadow-md: 3px 3px 2px 0px hsl(88 22% 35% / 0.15), 3px 2px 4px -1px hsl(88 22% 35% / 0.15);
  --shadow-lg: 3px 3px 2px 0px hsl(88 22% 35% / 0.15), 3px 4px 6px -1px hsl(88 22% 35% / 0.15);
  --shadow-xl: 3px 3px 2px 0px hsl(88 22% 35% / 0.15), 3px 8px 10px -1px hsl(88 22% 35% / 0.15);
  --shadow-2xl: 3px 3px 2px 0px hsl(88 22% 35% / 0.38);
  --destructive-hover: hsl(8.5 34.7% 42%);
}

:is(.dark, [data-theme="dark"]) [data-skin="kodama-grove"],
[data-skin="kodama-grove"]:is(.dark, [data-theme="dark"]) {
  --background: hsl(42.4 17.2% 19.4%);
  --foreground: hsl(38 41% 88%);
  --card: hsl(39 12% 23%);
  --card-foreground: hsl(38 41% 88%);
  --popover: hsl(39 12% 23%);
  --popover-foreground: hsl(38 41% 88%);
  --primary: hsl(95 16% 55%);
  --primary-foreground: hsl(27 12% 15%);
  --secondary: hsl(40 13% 31%);
  --secondary-foreground: hsl(38 41% 88%);
  --muted: hsl(39 13% 26%);
  --muted-foreground: hsl(33.3 11.5% 69.4%);
  --accent: hsl(44 27% 50%);
  --accent-foreground: hsl(27 12% 15%);
  --destructive: hsl(9.3 31.6% 44.1%);
  --destructive-foreground: hsl(40 41% 90%);
  --border: hsl(40 13% 31%);
  --input: hsl(40 13% 31%);
  --ring: hsl(95 16% 55%);
  --chart-1: hsl(95 16% 55%);
  --chart-2: hsl(92 19% 62%);
  --chart-3: hsl(104 11% 47%);
  --chart-4: hsl(44 27% 50%);
  --chart-5: hsl(104 11% 39%);
  --sidebar: hsl(42.4 17.2% 19.4%);
  --sidebar-foreground: hsl(38 41% 88%);
  --sidebar-primary: hsl(95 16% 55%);
  --sidebar-primary-foreground: hsl(27 12% 15%);
  --sidebar-accent: hsl(44 27% 50%);
  --sidebar-accent-foreground: hsl(27 12% 15%);
  --sidebar-border: hsl(40 13% 31%);
  --sidebar-ring: hsl(95 16% 55%);
  --shadow-2xs: 3px 3px 2px 0px hsl(88 22% 35% / 0.07);
  --shadow-xs: 3px 3px 2px 0px hsl(88 22% 35% / 0.07);
  --shadow-sm: 3px 3px 2px 0px hsl(88 22% 35% / 0.15), 3px 1px 2px -1px hsl(88 22% 35% / 0.15);
  --shadow: 3px 3px 2px 0px hsl(88 22% 35% / 0.15), 3px 1px 2px -1px hsl(88 22% 35% / 0.15);
  --shadow-md: 3px 3px 2px 0px hsl(88 22% 35% / 0.15), 3px 2px 4px -1px hsl(88 22% 35% / 0.15);
  --shadow-lg: 3px 3px 2px 0px hsl(88 22% 35% / 0.15), 3px 4px 6px -1px hsl(88 22% 35% / 0.15);
  --shadow-xl: 3px 3px 2px 0px hsl(88 22% 35% / 0.15), 3px 8px 10px -1px hsl(88 22% 35% / 0.15);
  --shadow-2xl: 3px 3px 2px 0px hsl(88 22% 35% / 0.38);
  --destructive-hover: hsl(9.3 31.6% 38.1%);
}

[data-skin="kodama-grove"] .shadow-xs { --tw-shadow: var(--shadow-xs); }
[data-skin="kodama-grove"] .shadow-sm { --tw-shadow: var(--shadow-sm); }
[data-skin="kodama-grove"] .shadow { --tw-shadow: var(--shadow); }
[data-skin="kodama-grove"] .shadow-md { --tw-shadow: var(--shadow-md); }
[data-skin="kodama-grove"] .shadow-lg { --tw-shadow: var(--shadow-lg); }
[data-skin="kodama-grove"] .shadow-xl { --tw-shadow: var(--shadow-xl); }
